python3 - <<'N'
import re,json
p='site/index.html';s=open(p).read();k='window.PATCH_NOTES = [\n';i=s.index(k)+len(k);rest=s[i:].split('\n')
new37="{v:'v1.1.37',d:'The inside of the Earth. Dig down anywhere and you pass through the layers of the Earth, each with a huge open cavern band and winding tunnels: limestone caves with underground streams, village ruins and a stone skull; lush caves with moss, blue glow grass, giant mushrooms and overgrown ruins; the deep dark of deepslate with crystal clusters and dark towers with lit windows; magma and basalt caverns with lava seas, basalt columns, blackstone cathedrals, a bridge over a lava river and lavafalls; the molten depths with purple crystal fields; and the abyssal shell of obsidian and violet glow, where a giant glowing eye waits at the top of gold steps. Below them the Earth is hollow, with a glowing yellow and orange sun in the middle, a sky blue haze, and green land, lakes and seas on the inside of the shell where down points outwards and the horizon curves up round you. Agartha now sits deep under the pyramid: a long drop shaft from the pyramid hall falls into a pool on top of the middle tower of a dark city of deepslate towers with glowing windows under a jagged rock roof, with floating saucers and a ring of sea behind big aquarium windows. A glowing lift pad on the city floor takes you down to the inner world and back, and an ice wall rings the land round it. The old floating Agartha and its long tunnel are gone. Near the coast the far sea picture now always has a hole round you so the real water and coast show.'}"
new36="{v:'v1.1.36',d:'The Earth, the Moon and Mars are round again. You walk all the way round a smooth sphere and the ground and the camera turn with you, with no flips and no staircase. The real world map stays, now painted on the round planet too. All ramps are gone, both the curved slopes on the ground and the corner stair ramps, so the terrain is plain blocks and plain stairs again. New land loads solid before you can reach it, so you no longer fall through the floor when you land, teleport or come back from space. The flying saucer now leaves without any boom.'}"
new35="{v:'v1.1.35',d:'The Earth, the Moon and Mars are now cube planets with six flat faces, so the ground under you is always level and there is no more tilted staircase or leaning camera. Walk off the edge of a face and the world turns smoothly under you onto the next face, so you can walk all the way round. The Earth now has the real world map on it, with Glencraft where Scotland is, Europe and Scandinavia nearby, and every continent out there to walk on. There is snow at the poles and on Greenland, desert in the Sahara, Arabia, central Australia, the Gobi and the American south west, and green land everywhere else. From space the Earth shows its painted faces, and the same continents show from the ground and from high in the air. The real world map is Natural Earth land data, which is public domain. There is no more unbreakable floor under the island, so you can dig down through every layer of the planet, and old saves are fixed too. The random explosion sound that played in the Agartha tunnels and in space is gone: it was the saucer leaving at dawn, which boomed wherever you were. Booms now only play for a real blast near you, and storm thunder never plays in space or underground. The flat sea picture that sat in front of the real water near the coast is gone too: near you, you now see the real blocks, the real water and the real sea bed.'}"
new34="{v:'v1.1.34',d:'Touch scrolling works again. Drag a finger up or down in the inventory, the crafting list, chests and the furnace to scroll, with a little glide when you let go, and a tap still picks an item. Falling now builds up speed the longer you fall, up to a high top speed, on the Earth, the Moon, Mars and out in space, so you no longer glide slowly down for ages, even with the jetpack on. The Moon and Mars still pull more gently than the Earth. A long fall still always leaves you at least half a heart. The Earth now shows the same continents from the ground, from high in the air and from orbit, so other lands no longer pop in only when you are far away.'}"
new="{v:'v1.1.33',d:'No more clipping. Every move you make is now checked in small steps, so walking, jumping, the jetpack and flying can no longer carry you into blocks on the map, the Earth, the Moon or Mars. If you ever do end up inside a block you are pushed straight back out. Patch notes fixed: every update from v1.1.14 on now shows its full notes again, not just the version number. Phones no longer get stuck on an old version: the game now checks for a new version when you open it and reloads itself to the newest one. Earth from space is now a real round planet: Glencraft shows as a snowy island and big green and brown continents are drawn on the globe, with no flat square or black patch. Corner stairs are now smooth corner ramps, both outer and inner corners, and you walk up them smoothly. On the Moon, Mars and the round Earth every one block step in the ground now has a smooth ramp over it, so walking all the way round has no bumps.'},"
new39="{v:'v1.1.39',d:'Round planets are walkable: away from the map the ground is laid in flat block terraces square to the grid, with steps of one or two blocks only where terraces meet, the camera stands upright on the ground (it leans to the round planet only high up) and stepping up glides instead of jumping. The saucer now lives on the sand beside the desert pyramid, and the pyramid is the only way into Agartha: the old hole by Blackstone Castle is gone. Pigs walk and roll in mud on the ground again. A faster start.'}"
new38="{v:'v1.1.38',d:'The old ice wall round the map is gone in new worlds and old saves, and blocks you placed are kept; the only ice wall is the ring round the planet. The land round Glencraft is now Great Britain: Glencraft sits in Scotland, with England to the south and Ireland to the west, and the snowy cliffs where the land carries on are gone. Teleport has a new Agartha button that lands you on the city floor. Smoother play and no black flashes. On phones the screen no longer flashes black: the resolution used to change between frames, which blanked the picture, and now it only changes right before a frame is drawn and much less often. Fog and sky colour ease instead of jumping. Big stutter fixes: the game no longer searches the whole world several times a frame for a few named objects, and no longer forces a page layout every frame. Digging and walking below the island are smooth: the inside of the Earth is generated once and cached, an edit redraws only the chunk you changed, chunks are rebuilt within a small time budget per frame, and old chunks stay drawn while new ones are built as you go down. A few island caves now carry on down through the bottom of the island in winding shafts into the first big cavern below, so you can go down without digging. Blackstone and dark stone cobble now break as fast as cobblestone with a pickaxe.'},"
new40="{v:'v1.1.40',d:'New God mode switch in the pause menu settings. When it is on nothing can hurt you: no fall, mob, lava, fire, void, drowning or hunger damage, and your health stays full. It is saved with your settings.'}"
new41="{v:'v1.1.41',d:'The ice wall is gone everywhere, with no icy edge, no cold and no ice ring left in new worlds or old saves. All of Agartha has moved to the North Pole of the real Earth: a flat snowy island sits on the pole with a glowing round hole that drops you into a pool on the middle tower of the city, and the lift down to the inside of the Earth is there too. The desert pyramid shaft is a second way in and takes you straight to the city. The saucer now lives on the North Pole island and races round the curve of the Earth to the pyramids at night, far faster than before. Breaking and placing blocks works anywhere on the round Earth.'}"
new42="{v:'v1.1.42',d:'The Earth is now a flat disc like the flat earth maps, with the North Pole in the middle, the continents round it and Antarctica as a white ring at the outside, all under a huge clear dome. A giant ice wall stands round the outer rim, and the old ice wall near Glencraft stays gone. Gravity is plain down everywhere on the disc, the ground is level, and you can break and place blocks anywhere. Glencraft is Scotland in Great Britain, drawn at twice its true size near the map, and the far continents are painted on the disc so you can see them from the air. The diggable layers, the caves, Agartha and the hollow Earth are all still under the land, with Agartha and the saucer home on the North Pole island in the middle. The Moon and Mars are round and walk exactly as they did before v1.1.39.'}"
new43="{v:'v1.1.43',d:'The old round globe no longer shows under the flat Earth, so the grey and white ring round Glencraft seen from space is gone, and so is the old dark sea square round the map. Great Britain and the land round Glencraft are now drawn in sharp detail from the air, matching the real blocks, with snow only at the poles and on the rim wall.'}"
new44="{v:'v1.1.44',d:'Earth is now just the UK. Glencraft sits where Scotland is with the same spawn and the same castles and builds, and England, Wales and Ireland follow their real coastlines, with open sea all round them and a wide field of sea ice past that. The globe, the flat disc, the dome and the other continents are gone. Agartha and the saucer home are on a small snowy island far north of Scotland, and the hollow Earth and the dig layers are still underneath. The Moon and Mars are unchanged.'}"
new45="{v:'v1.1.45',d:'Pigs walk upright on their legs with their heads on, and only now and then flop into the mud for one short roll before getting back up. Guns are held to the right of the view at full size and point at the crosshair, LT lines up the sights, each shot kicks with a flash at the barrel and a streak straight to the target.'}"
new89="{v:'v1.1.89',d:'Nothing outside the UK: the far sea and the sea bed under it now stop at the UK ice wall instead of running on for thousands of blocks.'}"
new88="{v:'v1.1.88',d:'One ocean: all the water in the game is now one sea at one level round the whole UK. Hidden water pockets under the old map are filled in, new worlds have no ponds above sea level, and the deep caves have no water pools. Water you poured yourself is never touched.'}"
new87="{v:'v1.1.87',d:'The real Agartha is now under Scotland. Find the cave mouth in the hills on the north coast, walk down the lit spiral cave and along the great tube tunnel to the crystal city with the Agarthans, where the saucer sleeps. The pause menu Teleport takes you to the cave or to Agartha. The separate Agartha world and the snowy island spiral are gone.'}"
new86="{v:'v1.1.86',d:'No more cliffs or steps where the original map meets the rest of the UK, the land eases smoothly into it. Placed blocks are drawn faster across the UK, so lots of building no longer slows the land down. New Teleport button in the pause menu, under Resume: Agartha cave entrance or Agartha tube tunnel.'}"
new85="{v:'v1.1.85',d:'Any block you place anywhere in the UK now stays, even in mid air far from the start, and it is kept in your save.'}"
new84="{v:'v1.1.84',d:'The original Agartha is back with its tall blue eyed Agarthans, own sky and inner sun. Way in: a spiral cave on the snowy island where the saucer lives, or the Agartha teleport to the big tube tunnel. One new deep world: huge open caverns all the way down, only small pools, no stone under obsidian, and the centre of the Earth is the biggest cave of all with no void.'}"
new83="{v:'v1.1.83',d:'No more water outside the UK. The far sea and sea bed now stop at the ice walls. The ruby ore scan that runs when you load a world is now split into tiny steps, so it no longer makes frames stutter on land.'}"
new82="{v:'v1.1.82',d:'You can fly the time box. Inside there is a big screen that shows a live view of where the box is going, and a brass steering wheel by the console. Stand at the console and press G or tap Fly. W S A D fly and steer, Space floats up and Shift sinks. Fly higher to go faster, right up into space to the Moon and Mars. Teleport trips now fade the box out with a whoosh and drop it down with a fun thump when it lands.'}"
new81="{v:'v1.1.81',d:'Deep down placing and breaking blocks works again, and what you place in caves is saved. The pickaxe swing now matches how fast the block really breaks, so the last swing lands as it breaks. Less lag underground: only the chunks round you are built down there, and two busy checks no longer run every frame. Mars is much bigger and sits up in the sky. You can land on it and walk all the way round it like the Moon.'}"
new80="{v:'v1.1.80',d:'More clean up. The dinosaurs were switched off long ago and are now deleted with their models and calls. The old whole Earth map, the painted far away Earth and the old Earth slab are deleted too. The UK and space stay.'}"
new79="{v:'v1.1.79',d:'The world is the UK now. A frosty ice wall runs all round the edge of the UK and you cannot get past it. Past the wall there is no old map, no sea and no ice ring. The sky above stays open so you can still fly to the Moon and Mars.'}"
new78="{v:'v1.1.78',d:'Clean up. The Backrooms and the old painting are gone for good and their spare block ids are free. Layer 5 now has Geode crust, layer 6 has Columnar basalt and layer 7 has glowing Sunstone. Deep in layers 6 and 7 the air shimmers with heat. Old saves still load and gold nuggets keep their count.'}"
new77="{v:'v1.1.77',d:'Time box near Earth spawn, bigger on the inside'}"
new76="{v:'v1.1.76',d:'Gun fixes. The right hand now closes round the wrist of the musket stock with the index finger on the trigger, instead of hanging open above the gun. In third person the right hand wraps the grip with the index finger on the trigger, and the left hand holds the barrel. Aiming down the sights no longer gets stuck after a jetpack flight: a lost mouse or touch release is cleared from the real button state and when you land.'}"
new75="{v:'v1.1.75',d:'The deep layers are full of things to find. Every cave layer has its own formations, spread so no two places look the same: stalactite forests, stalagmites, hourglass pillars and stone arches, flowstone in the limestone caves, giant glowing mushrooms in the lush caves, echo slate spikes and deep chasms in the deep dark, lavafalls and red hot floors in the magma layer and crystal geodes in the molten depths. Each layer also has its own new ancient ruins: an old stone bridge with gate towers, a standing stone circle, a gallery of stone guardians with crystal eyes, a stepped fire temple with a lava moat, a crystal obelisk shrine and a hall of gold capped columns. New blocks: red hot rock, flowstone, glowcap and echo slate, all minable, placeable and in the creative menu. Tall flames rise from red hot rock and magma near you underground.'}"
new74="{v:'v1.1.74',d:'About three times as many caves. Every world now has dozens of extra big open caverns under the land, joined by winding tunnels, and the deepest ones have long lava trenches in the floor. They only cut through natural rock, never blocks you placed, and never under the sea, lakes or rivers. Any water next to a new cave is sealed with stone so nothing floods.'},"
new73="{v:'v1.1.73',d:'Fixes from a full test run. Some old pyramid code was still running and failing every few seconds, because the pyramid is gone and the volcano crash site took its place. It now leaves the volcano alone. The old north edge code that no longer applies to the UK map has stopped failing too. Everything else in the test run passed.'},"
new72="{v:'v1.1.72',d:'No more see through rock below Y 0. From a cave under Y 0 you could look straight up through the stone into all the caves and the sky above, because the bottom layer of the world never drew its underside. It does now, so the roof of a deep cave is solid rock again.'},"
new71="{v:'v1.1.71',d:'Tornadoes. Pick Tornado in the Weather row of the pause menu and a tall spinning funnel comes down in a storm near you and roams the land for about two minutes. It rips up trees, ground and castle stone in its path and flings the pieces out for you to pick up, throws mobs about, and lifts and spins you if you get too close. It never touches blocks you placed, and it only breaks a few blocks a second so the game stays smooth. Press Tornado again to send it away.'},"
new70="{v:'v1.1.70',d:'Water acts like the right kind of water. Only the open sea has waves now. Rivers keep flowing one way as a gentle stream, and ponds and lakes lie still and only ripple in rings when you step or fall in. In a thunderstorm the sea waves get big and wild, and a strong wind pushes you about when you are out in the open.'},"
new69="{v:'v1.1.69',d:'Bigger, richer deep layers. Every layer deep under the ground is now a much taller open cave world, and there are about three times as many winding tunnels joining the layers together. Each layer has its own ores: coal, iron and copper near the top, lapis in the lush caves, silver, diamond and redstone in the deep dark, gold and ruby by the magma, cobalt in the molten depths and diamond and gold round the eye at the bottom. The stray puddles on the cave floors are gone, leaving just a few streams in the limestone caves.'},"
new68="{v:'v1.1.68',d:'The Moon moves again. It rises in the evening, crosses the sky through the night and sets at dawn with the day and night cycle, just like before. At midnight it lines up exactly with the real Moon you can fly to, and it is still the same size and painted from the real Moon ground.'},"
new67="{v:'v1.1.67',d:'One Moon. The moon in the night sky is now the real Moon you can fly to and land on. It sits in the same direction as the real one and is the same size it would really look from where you stand, painted from the real Moon ground. When you fly up into space the sky disc goes away and you see the real Moon itself.'},"
new66="{v:'v1.1.66',d:'The UK from space. Fly high or go to space and the whole of Great Britain and Ireland now stay in view below you, built from the real ground heights and block colours of the world, with the sea round them. It is one light mesh that only shows when you are high up, and the view distance is raised while you are up there so nothing is cut off.'},"
new65="{v:'v1.1.65',d:'Agartha mountain tunnel fixes. The tunnel now runs all the way out of the hill even where the ground dips and rises again, the hall is never cut next to a lake or the sea so it can not flood, and it is carved again a few times while the world finishes loading so nothing fills it back in. The far sea bed sheet no longer shows when you fly very high.'},"
new64="{v:'v1.1.64',d:'One sea. The seam line where the Glencraft water met the UK sea is gone. The far sea now uses the same water as the map, at the same level, with the same texture and waves, and the darker side walls and bottoms of the sea blocks at the edge of the drawn area are no longer shown. The far sea also has a sea bed under it, so it is no longer paler than the near sea.'},"
new63="{v:'v1.1.63',d:'Agartha has a way in through a mountain again. The biggest natural hill on the map now has a big tunnel mouth in its side. The tunnel slopes down into a huge open hall hollowed out inside the hill, lit by glowing rock. Stand on the glowing pad in the middle of the hall to go down to the Agartha city. Blocks you placed are never touched.'},"
new62="{v:'v1.1.62',d:'Smoother player model. The HD player now has rounded smooth shading with no hard creases, real fingers and a thumb on each hand, and a lighter low detail version that swaps in only when the player is far away.'},"
new61="{v:'v1.1.61',d:'TV sound fix. The TV is now much louder and carries further across the room. There is a new TV volume slider in Settings, right under Sound effects. It saves with your other settings and changes the sound straight away.'},"
new60="{v:'v1.1.60',d:'Grip fix. In first person your right hand now closes round the wrist of the musket stock with the trigger finger at the trigger, instead of hanging open under the gun.'},"
new59="{v:'v1.1.59',d:'Sprint and storms. When you sprint with a gun it now drops low across your chest with the barrel pointing down and away, so the middle of the screen stays clear, the gun never swings into your face, the elbows bend and the bob is a gentle up and down in step with your feet. The Thunner Cloudie now hits mobs with a big lightning zap: a thick forked bolt, a bright flash, a glow on the ground and a spray of sparks, and the bolt follows the mob it aims at. The loud explosion sound is gone and is now a soft short thump, and the volcano and thunder are quieter too. The thumb now curls round the grip instead of bending back. In third person guns sit level in both hands with the stock at the shoulder, tools are held upright by the handle, and blocks and drinks sit in the palm at a sensible size.'},"
new58="{v:'v1.1.58',d:'New TV shows. The TV now plays your own edits, one after another on a loop, with the sound coming from the TV. The old cartoon clips are gone.'},"
new57="{v:'v1.1.57',d:'Hands and body. The thumb now wraps round what you hold instead of sticking out, the fingers sit apart and close round handles, the trigger finger rests on the trigger, and guns sit higher so both hands show on them, phones in portrait included. Reload plays a smooth reload with the hands working the gun whenever the mag is not full, unlimited bullets too. No more square shot bits: shots now give round fire sparks, soft smoke and dust puffs. Looking down shows the new body with its kilt or your leggings and chest armour, and the kilt hides under leggings. The new model blinks again.'},"
new56="{v:'v1.1.56',d:'Fix. Below Y0 the stone no longer looks pale and lit like the surface, and the bottom of the old world now closes off the caves above, so you can no longer see up through it. Deep caves are dark like real caves.'},"
new55="{v:'v1.1.55',d:'Fixes. Aiming down the sights can no longer get stuck with the camera inside the gun after jetpack flight. Blocks you place deep underground, out on the planet and in Agartha now show up. Enchantments stay on your items after you leave and reload a world. The diamond pickaxe now digs like Efficiency 10 and breaks every breakable block fast, obsidian and deepslate included. Hands now really grip what they hold: a closed fist round tool handles, the trigger finger on the trigger, the left hand under the rifle foregrip, blocks sitting in the palm and drinks held in the hand. Aiming down the sights lines the sights up with the crosshair at a sensible size with both hands on the gun. The clouds are off again, phones included. The on screen RT button fires the gun, and holding it keeps firing; bedrock stays unbreakable.'}"
new54="{v:'v1.1.54',d:'New body, arms and deaths. In first person you now see real shaped arms with hands and fingers, rifles held in both hands, pistols in both hands while aiming, with sway, bob, recoil, reload, swap and mining moves, and your body and kilt when you look down. In third person the player is a new detailed model with bending elbows and knees and matching armour. Legs follow the stick for slow walk, walk, run, strafe and backpedal, jumps have a takeoff, air and landing pose, and guns and tools are held properly with rifles in both hands. Any kill now leaves a body that falls the way the hit came from, with a wound mark, a spreading pool, blood drops and a wall splat for gun kills. Skeletons fall apart into a heap of bones with no blood. Bodies stay for a few minutes and the oldest fade first. Bullets now throw sparks off stone and metal, dust off dirt and wood, leave bullet holes and a puff on mobs. Treemen can now step out beside oak trees at night.'}"
new53="{v:'v1.1.53',d:'New sounds. Birds by day are now British and Scottish: robins, blackbirds, wrens, skylarks and curlews, with gulls by the coast and the odd plane far overhead. At night you hear tawny owls, the wind and running water near rivers. All of it fades out when you go indoors or underground, so there are no birds in caves. Each cave layer has its own music: drips and streams in the limestone caves, soft chimes in the lush caves, low clicks in the deep dark, rumbles in the lava caves, glassy tones in the crystal depths, deep throbs in the shell, and warm bells in the hollow Earth and cavern cities. Rooms and caves now echo: every sound, from footsteps and digging to mobs and guns, gets a reverb, short in a small room and long in a big cavern.'}"
new52="{v:'v1.1.52',d:'The held map now says WALES clearly: the country names sit in the right places and no longer run into each other, and castle names are left off the big UK map so it stays tidy. Smoother on phones: the unused torch lights are switched off while nothing is lit, so walking and flying both run faster (about 15 frames a second on the ground and 11 high in the air in our phone test, up from 13 and 9). Behind the scenes the game code is sorted into named modules with a map of what each one does, and old unused code is gone, including the old sea disc and ice ring pictures that were already switched off. The held map now shows one sea in one blue everywhere, with no lighter box round the old Glencraft area. Volcanoes are fixed: the glow and smoke that floated over the sea now sit inside the Ardnamurchan crater, so each volcano is one cone with lava in its top. 36 more old volcano sites are added across Scotland, Northern Ireland, the Isle of Man, the Lake District, Wales, the Midlands and the South West, plus Rockall. Warm springs bubble at Bath, Buxton and Matlock.'}"
new51="{v:'v1.1.51',d:'All of the UK and Ireland past Scotland is now full Glencraft land: grass, heather, sandy beaches, snowy tops and regional rock, with trees, flowers, ferns, ores and small caves, never under water. The sea is real water everywhere out to the ice ring and you can see it. The land out there now loads around you from far away and from the air, like Glencraft, instead of only fog. Digging down can no longer throw you back to spawn or up onto the land, anywhere on the map, and if you ever fall below the very bottom of the world you are put back on the ground above. The old bass and piano soundtrack is gone, replaced by calm nature sounds: wind, a burn and birds by day, crickets and an owl at night. The flat blue sea disc and the old far map pictures are gone, and when you fly high the block in your hand is hidden.'}"
new50="{v:'v1.1.50',d:'If you save and quit while out past Scotland, in England, Wales or Ireland, you now load back in exactly where you were, even underground, instead of being sent back to spawn. When you fly high, the block in your hand is now hidden so nothing covers the view of the land. On phones the distance you see from high up is tuned a little shorter so it stays smooth.'}"
new49="{v:'v1.1.49',d:'Fix: digging down past Y0 no longer throws you back up onto the land. You can now dig and fall all the way down to the core and the hollow Earth, and you are only rescued if you drop below the true bottom of the world. The simple low detail ground seen from high up is gone. Real block chunks now stay drawn when you fly up, and you see further the higher you go. Clouds are fully off. Your legs and the block in your hand no longer cover the view when you look straight down while flying. Holding a gun, LT now only aims and never places a block. The map you hold now shows the whole UK and Ireland with the countries named, and out past Scotland the ground changes by region: bogs in Ireland, basalt in Antrim, slate in Wales, heather on the Pennines, granite moors in Devon and Cornwall, chalk in the south east, fens in East Anglia and red sandstone in the Midlands.'}"
new48="{v:'v1.1.48',d:'No more desert or pyramid in Scotland. That land is now Highland ground like the rest, and the North island hole is the only way down to Agartha. Old volcanoes now stand at the real volcanic sites of the UK and Ireland, from Arthurs Seat, Skye and Mull to Staffa and the Giants Causeway basalt columns, the Lake District and Snowdonia, and two craters on Mull and Ardnamurchan hold lava. The saucer night trip now flies to the Ardnamurchan crater. No more clouds, and no painted map picture over the land when you fly up. From high in the sky you now see the real ground below, built from the actual blocks and your builds. The pistol no longer vanishes when you aim down the sights with LT, and the Fly UFO button hides while you aim.'}"
new47="{v:'v1.1.47',d:'Seen from high in space, Scotland now joins England with no strip of sea. Gun hits throw smaller dust and the guns are brighter in your hand.'}"
new46="{v:'v1.1.46',d:'Glencraft is now the real shape of Scotland. The old square map, its round island and the ring of sea are gone. The Highlands have heather, crags, lochs and snowy tops, the Lowlands and Southern Uplands roll on into England, and the spawn, the three castles with their bridges and the desert with the pyramid sit inland. Old saves are converted once, a backup is kept first and every block you placed stays. Gun smoke is smaller and held guns are brighter. You can dig below Y1 again everywhere, right down through the deep layers to the hollow Earth.'}"
lines=[new89,new88,new87,new86,new85,new84,new83,new82,new81,new80,new79,new78,new77,new76,new75,new74,new73,new72,new71,new70,new69,new68,new67,new66,new65,new64,new63,new62,new61,new60,new59,new58,new57,new56,new55,new54,new53,new52,new51,new50,new49,new48,new47,new46,new45,new44,new43,new42,new41,new40,new39,new38,new37,new36,new35];j=0
while rest[j].startswith("{v:'v"): lines.append(rest[j]); j+=1
seen=set();out=[]
for l in lines:
    v=l[4:l.index("'",5)]
    if v in seen: continue
    seen.add(v)
    m=re.match(r"^\{v:'(v[\d.]+)',d:'(.*)'\},?$",l)
    if m:
        n=int(v.split('.')[-1]);d='2026-11-03' if n>=25 else '2026-11-02'
        parts=[x.strip() for x in re.split(r'(?<=\.)\s+(?=[A-Z])',m.group(2)) if x.strip()]
        l="{v:'%s', d:'%s', notes:[%s]},"%(v,d,','.join("'"+x.replace("'","")+"'" for x in parts))
    out.append(l if l.endswith(',') else l+',')
key=lambda l:[int(x) for x in l[5:l.index("'",5)].split('.')]
out.sort(key=key,reverse=True)
s=s[:i]+'\n'.join(out+rest[j:]);open(p,'w').write(s)
v=re.search(r"GAME_VERSION = '([\d.]+)'",s).group(1);open('site/version.json','w').write(json.dumps({'v':v}))
print('notes',len(out),'top',[l[:12] for l in out[:3]],'ver',v)
N
cp site/index.html /tmp/srv/new250.html; cp site/sw.js site/version.json /tmp/srv/
